// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceEncryptedHttp {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceEncryptedHttp = UniffiVTableCallbackInterfaceEncryptedHttp(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeEncryptedHttp.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface EncryptedHttp: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeEncryptedHttp.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface EncryptedHttp: handle missing in uniffiClone")
            }
        },
        post: { (
            uniffiHandle: UInt64,
            path: RustBuffer,
            body: RustBuffer,
            upload: Int8,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> EncryptedReply in
                guard let uniffiObj = try? FfiConverterTypeEncryptedHttp.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.post(
                     path: try FfiConverterString.lift(path),
                     body: try FfiConverterString.lift(body),
                     upload: try FfiConverterBool.lift(upload)
                )
            }

            let uniffiHandleSuccess = { (returnValue: EncryptedReply) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterTypeEncryptedReply_lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeDbError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceEncryptedHttp> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceEncryptedHttp>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitEncryptedHttp() {
    uniffi_dblayer_fn_init_callback_vtable_encryptedhttp(UniffiCallbackInterfaceEncryptedHttp.vtablePtr)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEncryptedHttp: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<EncryptedHttp>()

    typealias FfiType = UInt64
    typealias SwiftType = EncryptedHttp

    public static func lift(_ handle: UInt64) throws -> EncryptedHttp {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return EncryptedHttpImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: EncryptedHttp) -> UInt64 {
         if let rustImpl = value as? EncryptedHttpImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EncryptedHttp {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: EncryptedHttp, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


